using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;
namespace RebirthEntityStudio {
 [Serializable] public sealed class BodyTemplate {
  public int version;public string sourceCommit,license;public float[] positions,uv,jointPositions;public int[] sourceIds,triangles;public string[] jointNames;public FaceControl[] controls;public FaceMorph[] morphs,jointMorphs;
  [NonSerialized] public string contentHash,extensionHash,topologyHash;[NonSerialized] public BodyTopology topology;
 }
 [Serializable] public sealed class BodyRecipe {
  public BodyDamageSettings damage=new BodyDamageSettings();public bool includeHeadDetail;public bool authoredSurfaceFrames;public string authoredBodyGuid="",authoredBodyHash="";public int version=1;public string name="Body",templateHash="",referenceGuid="",bodyImageReportGuid="",generationReportGuid="",sourceHeadSettingsGuid="",skinTextureGuid="",skinReportGuid="",extensionHash="";public float age=.35f,masculine,height=1.7f;public Color skinTint=Color.white;public FaceValue[] values=new FaceValue[0];
  public bool fitVisibleWidths=true;public string bodyFoundationGuid="";public int subdivision;public string topologyHash="";public bool inheritHeadAge,inheritHeadShape;public BodySkinPatternSettings skinPattern=new BodySkinPatternSettings();public string attachedHeadSettingsGuid="";public float attachedHeadSize=1,neckJoinHeight=1.49f,neckShortening=.04f;public int sourceSkinTintVersion;public Color sourceSkinTint=Color.white;public string pigmentMaskGuid="";public BodySurfaceSettings surface=new BodySurfaceSettings();public int pigmentVersion;public Color nippleTint=Color.white,areolaTint=Color.white;public float areolaSize=1;
  public float Get(FaceControl control){return values.FirstOrDefault(v=>v.id==control.id)?.value??control.defaultValue;}
  public void Set(string key,float value){var item=values.FirstOrDefault(v=>v.id==key);if(item==null)values=values.Concat(new[]{new FaceValue(key,value)}).ToArray();else item.value=value;}
  public void Validate(BodyTemplate template){if(damage==null)damage=new BodyDamageSettings();damage.Validate();if(authoredSurfaceFrames&&string.IsNullOrEmpty(authoredBodyGuid))throw new InvalidDataException("Surface-bound deformation requires an authored body foundation");RebirthBodySubdivision.Validate(template,this);if(skinPattern==null)skinPattern=new BodySkinPatternSettings();skinPattern.Validate();if(version!=1)throw new InvalidDataException("Unsupported body recipe version");if(attachedHeadSize==0)attachedHeadSize=1;if(neckJoinHeight==0)neckJoinHeight=1.49f;foreach(float v in new[]{attachedHeadSize,neckJoinHeight,neckShortening})if(float.IsNaN(v)||float.IsInfinity(v))throw new InvalidDataException("Invalid head attachment setting");attachedHeadSize=Mathf.Clamp(attachedHeadSize,.8f,1.2f);neckJoinHeight=Mathf.Clamp(neckJoinHeight,1.44f,1.50f);neckShortening=Mathf.Clamp(neckShortening,0,.07f);if(surface==null)surface=new BodySurfaceSettings();surface.Validate();if(!string.IsNullOrEmpty(templateHash)&&templateHash!=template.contentHash)throw new InvalidDataException("Body settings require their original template revision");templateHash=template.contentHash;if(!string.IsNullOrEmpty(extensionHash)&&!RebirthBodyComposition.CompatibleExtension(extensionHash,template.extensionHash))throw new InvalidDataException("Body settings require their matching regional target data");extensionHash=template.extensionHash;values=values??new FaceValue[0];if(sourceSkinTintVersion==0){sourceSkinTint=Color.white;sourceSkinTintVersion=1;}if(sourceSkinTintVersion!=1)throw new InvalidDataException("Unsupported source skin tint");foreach(float v in new[]{sourceSkinTint.r,sourceSkinTint.g,sourceSkinTint.b})if(float.IsNaN(v)||float.IsInfinity(v)||v<0)throw new InvalidDataException("Invalid source skin tint");sourceSkinTint.a=1;if(pigmentVersion==0){nippleTint=Color.white;areolaTint=Color.white;areolaSize=1;pigmentVersion=1;}if(pigmentVersion!=1)throw new InvalidDataException("Unsupported pigment settings");foreach(float value in new[]{nippleTint.r,nippleTint.g,nippleTint.b,areolaTint.r,areolaTint.g,areolaTint.b,areolaSize})if(float.IsNaN(value)||float.IsInfinity(value))throw new InvalidDataException("Invalid pigment setting");nippleTint=new Color(Mathf.Clamp(nippleTint.r,0,3),Mathf.Clamp(nippleTint.g,0,3),Mathf.Clamp(nippleTint.b,0,3),1);areolaTint=new Color(Mathf.Clamp(areolaTint.r,0,3),Mathf.Clamp(areolaTint.g,0,3),Mathf.Clamp(areolaTint.b,0,3),1);areolaSize=Mathf.Clamp(areolaSize,.4f,2);foreach(float value in new[]{age,masculine,height,skinTint.r,skinTint.g,skinTint.b})if(float.IsNaN(value)||float.IsInfinity(value))throw new InvalidDataException("Invalid body setting");age=Mathf.Clamp01(age);masculine=Mathf.Clamp01(masculine);height=Mathf.Clamp(height,1.2f,2.3f);skinTint=new Color(Mathf.Clamp01(skinTint.r),Mathf.Clamp01(skinTint.g),Mathf.Clamp01(skinTint.b),1);foreach(var value in values){var control=template.controls.FirstOrDefault(c=>c.id==value.id);if(control==null||float.IsNaN(value.value)||float.IsInfinity(value.value))throw new InvalidDataException("Invalid body morph: "+value.id);value.value=Mathf.Clamp(value.value,control.min,control.max);}}
 }
 public static class RebirthBodyGeneratorModel {
  public static BodyTemplate ReadTemplate(){string path=AssetDatabase.FindAssets("BodyTemplate t:TextAsset").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/BodyGeneratorData/BodyTemplate.json",StringComparison.Ordinal));if(path==null)throw new FileNotFoundException("Install the CC0 body template");var asset=AssetDatabase.LoadAssetAtPath<TextAsset>(path);var result=JsonUtility.FromJson<BodyTemplate>(asset.text);if(result.version!=1||result.license!="CC0-1.0")throw new InvalidDataException("Unsupported body template");using(var sha=System.Security.Cryptography.SHA256.Create())result.contentHash=BitConverter.ToString(sha.ComputeHash(asset.bytes)).Replace("-","").ToLowerInvariant();RebirthBodyComposition.Attach(result);RebirthBodySubdivision.Attach(result);return result;}
  public static Mesh Build(BodyTemplate template,BodyRecipe recipe){recipe.Validate(template);if(!string.IsNullOrEmpty(recipe.authoredBodyGuid))return RebirthAuthoredBody.Build(template,recipe);var points=Enumerable.Range(0,template.positions.Length/3).Select(i=>new Vector3(template.positions[i*3],template.positions[i*3+1],template.positions[i*3+2])).ToArray();var targets=template.morphs.ToDictionary(m=>m.id);var identity=new FaceRecipe{age=recipe.age,masculine=recipe.masculine};RebirthFaceIdentity.Apply(points,targets,identity);RebirthBodyComposition.Apply(points,targets,recipe);foreach(var control in template.controls){float value=recipe.Get(control);foreach(string key in value<0?control.negative:control.positive)RebirthFaceGeneratorModel.Apply(points,targets[key],Mathf.Abs(value));}var coordinates=Enumerable.Range(0,points.Length).Select(i=>new Vector2(template.uv[i*2],template.uv[i*2+1])).ToArray();int[] triangles;RebirthBodySubdivision.Evaluate(template,recipe,ref points,ref coordinates,out triangles);float bottom=points.Min(p=>p.y),scale=recipe.height/Mathf.Max(.1f,points.Max(p=>p.y)-bottom);for(int i=0;i<points.Length;i++)points[i]=new Vector3(points[i].x*scale,(points[i].y-bottom)*scale,points[i].z*scale);var mesh=new Mesh{name=recipe.name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.vertices=points;mesh.uv=coordinates;mesh.triangles=triangles;mesh.RecalculateNormals();var normals=mesh.normals;foreach(var group in Enumerable.Range(0,points.Length).GroupBy(i=>Vector3Int.RoundToInt(points[i]*1000000))){var n=group.Aggregate(Vector3.zero,(sum,i)=>sum+normals[i]).normalized;foreach(int i in group)normals[i]=n;}mesh.normals=normals;mesh.RecalculateTangents();mesh.RecalculateBounds();return mesh;}
  public static string FoundationPath(BodyRecipe recipe){if(!string.IsNullOrEmpty(recipe.bodyFoundationGuid)){string path=AssetDatabase.GUIDToAssetPath(recipe.bodyFoundationGuid);if(string.IsNullOrEmpty(path)||!File.Exists(path)||AssetDatabase.LoadAssetAtPath<Texture2D>(path)==null)throw new FileNotFoundException("Body skin foundation is missing");return path;}return AssetDatabase.FindAssets("SkinFoundation t:Texture2D").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/FaceGeneratorData/SkinFoundation.png",StringComparison.Ordinal));}
  static Shader BodyShader(){string path=AssetDatabase.FindAssets("BodySkin t:Shader").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/REBIRTHEntityStudio/Shaders/BodySkin.shader",StringComparison.Ordinal));return (path==null?null:AssetDatabase.LoadAssetAtPath<Shader>(path))??Shader.Find("REBIRTH/Body Skin")??Shader.Find("Standard");}
  public static Material Skin(BodyRecipe recipe){var material=new Material(BodyShader()){name="Whole body skin",color=recipe.skinTint*recipe.sourceSkinTint,hideFlags=HideFlags.HideAndDontSave};try{string path=FoundationPath(recipe);if(!string.IsNullOrEmpty(recipe.skinTextureGuid)){path=AssetDatabase.GUIDToAssetPath(recipe.skinTextureGuid);if(string.IsNullOrEmpty(path)||AssetDatabase.LoadAssetAtPath<Texture2D>(path)==null)throw new FileNotFoundException("Body skin texture is missing");}if(path!=null)material.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);string mask=AssetDatabase.FindAssets("BodyPigmentRegions t:Texture2D").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/BodyGeneratorData/BodyPigmentRegions.png",StringComparison.Ordinal));if(!string.IsNullOrEmpty(recipe.pigmentMaskGuid)){mask=AssetDatabase.GUIDToAssetPath(recipe.pigmentMaskGuid);if(string.IsNullOrEmpty(mask)||AssetDatabase.LoadAssetAtPath<Texture2D>(mask)==null)throw new FileNotFoundException("Body pigment region texture is missing");}if(mask!=null&&material.HasProperty("_RegionMask")){var importer=(TextureImporter)AssetImporter.GetAtPath(mask);if(importer.sRGBTexture||importer.textureCompression!=TextureImporterCompression.Uncompressed){importer.sRGBTexture=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();}material.SetTexture("_RegionMask",AssetDatabase.LoadAssetAtPath<Texture2D>(mask));material.SetColor("_NippleTint",recipe.nippleTint);material.SetColor("_AreolaTint",recipe.areolaTint);material.SetFloat("_AreolaSize",recipe.areolaSize);}RebirthBodySurface.Apply(material,recipe.surface);RebirthBodyDamage.Apply(material,recipe.damage);return material;}catch{UnityEngine.Object.DestroyImmediate(material);throw;}}
 }
